CREATE DATABASE CongTyXayDungGOcreate table ChucVu(MaCV nvarchar(10) not null primary key,TenCV nvarchar(50))create table PhongBan(MaPB nvarchar(10) not null primary key,TenPB nvarchar(50),TruongPhong nvarchar(10))create table NhanVien(MaNV nvarchar(10)  not null,HoNV nvarchar(10),TenNV nvarchar(50),NgaySinh DATE,GioiTinh varchar(10),DiaChi nvarchar(50),QQuan nvarchar(50),Email nvarchar(50),SDT varchar(15),Luong int,MaPB nvarchar(10) not null,MaCV nvarchar(10) not null,primary key (MaNV))-----Ràng buộc-----alter table NhanVienadd constraint RB_NV_PB_MaPBforeign key (MaPB)references PhongBan(MaPB)ALTER TABLE NhanVienADD CONSTRAINT RB_NV_CV_MaCV FOREIGN KEY (MaCV) REFERENCES ChucVu(MaCV)alter table PhongBanadd constraint RB_NV_PB_TruongPhongforeign key (TruongPhong)references NhanVien(MaNV)create table DuAn(MaDA nvarchar(10) not null,TenDA nvarchar(50),DiaDiem nvarchar(50),MaPB nvarchar(10),KinhPhi decimal(18,2),NgayKhoiCong date,NgayKetThucDuKien date,TrangThai nvarchar(20),MaKH nvarchar(10),primary key(MaDA),CONSTRAINT CHK_DuAn_NgayKetThuc CHECK (NgayKetThucDuKien >= NgayKhoiCong),CONSTRAINT CHK_DuAn_TrangThai CHECK (TrangThai IN (N'Đang thiết kế', N'Đang thi công', N'Đã hoàn thành', N'Tạm dừng', N'Đã hủy')),)create table PhanCong(MaNV nvarchar(10) not null,MaDA nvarchar(10) not null,VaiTro nvarchar(50),NgayBatDauCongViec DATE,NgayKetThucCongViec DATE,CONSTRAINT UNQ_PhanCong_NhanVien_DuAn_VaiTro UNIQUE (MaNV, MaDA),CONSTRAINT CHK_PhanCong_NgayKetThuc CHECK (NgayKetThucCongViec >= NgayBatDauCongViec),primary key (MaNV,MaDA))create table KhachHang(MaKH nvarchar (10) PRIMARY KEY,TenKH nvarchar (50),SDT nvarchar (15),Email nvarchar (20),)-----Ràng buộc-----ALTER TABLE PhanCong ADD CONSTRAINT RB_PhanCong_NhanVien_MaNVFOREIGN KEY (MaNV) REFERENCES NhanVien(MaNV)ALTER TABLE PhanCong ADD CONSTRAINT FK_PhanCong_DuAn_MaDAFOREIGN KEY (MaDA) REFERENCES DuAn(MaDA)alter table DuAnadd constraint FK_PhongBan_DuAn_MaPBforeign key (MaPB)references PhongBan(MaPB)alter table DuAnadd constraint RB_DuAn_KHforeign key (MaKH)references KhachHang(MaKH)create table NhaCungCap(MaNCC nvarchar (10) PRIMARY KEY,TenNCC nvarchar (50),SDT nvarchar (15),Email nvarchar (20),DiaChi nvarchar (200),LoaiHinh varchar(20))create table KhoThietBi(MaThietBi nvarchar(10) PRIMARY KEY,TenThietBi varchar(50),SoSeri int UNIQUE,TrangThai varchar(20)CONSTRAINT CHK_ThietBi_TrangThai CHECK (TrangThai IN (N'Sẵn sàng', N'Đang sửa chữa', N'Đang sử dụng', N'Thanh lý')))create table KhoVatTu(MaVatTu nvarchar(10) PRIMARY KEY,TenVatTu nvarchar(50),DonViTinh nvarchar(20),MoTa nvarchar(500),CONSTRAINT CHK_VatTu_DonViTinh CHECK (DonViTinh IN (N'Tấn', N'm3', N'Cây', N'Kg', N'Cái', N'Lít', N'Bao')))create table ThongTinDonNhapHang(MaDonHang nvarchar(10) PRIMARY KEY,NgayDatHang date default GETDATE(),MaDA nvarchar(10),MaNCC nvarchar(10),TongGiaTri decimal(18, 2) default 0,TrangThai nvarchar(20),CONSTRAINT CHK_DonNhapHang_TongGiaTri CHECK (TongGiaTri >= 0),CONSTRAINT CHK_DonNhapHang_TrangThai CHECK (TrangThai IN (N'Chờ duyệt', N'Đã duyệt', N'Đã giao hàng', N'Đã hủy')))-----RÀNG BUỘC-----alter table ThongTinDonNhapHangadd constraint RB_ThongTinDonNhapHang_DuAnforeign key (MaDA)references DuAn(MaDA)alter table ThongTinDonNhapHangadd constraint RB_ThongTinDonNhapHang_NhaCungCapforeign key (MaNCC)references NhaCungCap(MaNCC)create table ChiTietHoaDonNhapHang(MaHoaDon nvarchar(10) PRIMARY KEY,MaDonHang nvarchar(10),MaVatTu nvarchar(10),MaThietBi nvarchar(10),SoLuong decimal(18,2),DonGia decimal(18,2),ThanhTien AS (SoLuong * DonGia) PERSISTED,CONSTRAINT UNQ_ChiTiet_DonHang_VatTu UNIQUE (MaDonHang, MaVatTu),CONSTRAINT CHK_ChiTiet_SoLuong CHECK (SoLuong > 0),CONSTRAINT CHK_ChiTiet_DonGia CHECK (DonGia >= 0))-----RÀNG BUỘC-----alter table ChiTietHoaDonNhapHangadd constraint RB_ChiTiet_DonHangforeign key (MaDonHang)references ThongTinDonNhapHang(MaDonHang)alter table ChiTietHoaDonNhapHangadd constraint RB_ChiTiet_VatTuforeign key (MaVatTu)references KhoVatTu(MaVatTu)alter table ChiTietHoaDonNhapHangadd constraint RB_ChiTiet_ThietBiforeign key (MaThietBi)references KhoThietBi(MaThietBi)-----Format date-----set dateformat dmY